resource "aws_iam_role_policy" "main" {
  name = var.name
  role = aws_iam_role.main[0].id
  count = var.stack_with_role ? 1 : 0

  policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Action": [
        "s3:*"
      ],
      "Effect": "Allow",
      "Resource": "*"
    }
  ]
}
EOF
}

